    created_at BIGINT NOT NULL
);
COMMENT ON TABLE conflict_history IS '冲突历史：声明与解除均只追加，固化操作人、角色、原因与区间，任何后续操作不得改写';
COMMENT ON COLUMN conflict_history.history_id IS '历史记录 ID，自增，排序辅助';
