        assertThat(declareConflictsBatch(docId, "bob", overlapExisting, newRequestId()).status()).isEqualTo(409);

        // 合法批：两条相邻区间，按请求顺序返回且已有评审被标记
        String validBatch = "[{\"language\":\"en\",\"validFrom\":" + (T0 + 1000) + ",\"validTo\":"
                + (T0 + 2000) + ",\"reason\":\"批量一\"},"
